<template><section v-if="restaurant" class="restaurant-page"><NavHeader :title="restaurant.name" @back="goBack" /><div class="restaurant-hero"><RestaurantArt :name="restaurant.name" :color="restaurant.color" /><div class="hero-badge"><AppIcon name="fork" :size="13" />演示餐厅</div><div class="host-avatar"><CharacterAvatar :character="restaurant.character" :name="restaurant.host" /></div></div><div class="detail-content"><div class="restaurant-heading"><h2>{{ restaurant.name }}</h2><p>{{ restaurant.cuisine }} <i>·</i> {{ restaurant.price ? `人均 ¥${restaurant.price}` : '人均价格未知' }} <i>·</i> 直线 {{ store.distance(restaurant.id) }} km</p><div class="chips"><span v-for="tag in restaurant.tags" :key="tag" class="chip green">{{ tag }}</span></div></div><div class="restaurant-info"><div><AppIcon name="clock" :size="17" /><span><b>营业时间</b>{{ restaurant.hours || '暂无可靠营业信息，请向商家确认' }}</span></div><div><AppIcon name="pin" :size="17" /><span><b>地址</b>{{ restaurant.address }}</span></div><div><AppIcon name="star" :size="17" /><span><b>评分</b>{{ restaurant.rating || '暂无可核实评分' }}</span></div></div><div class="host-note"><div class="host-portrait"><CharacterAvatar :character="restaurant.character" :name="restaurant.host" portrait /></div><div><b>{{ restaurant.host }}想对你说</b><p>“{{ restaurant.intro }}”</p></div></div><div class="section-heading"><h2>为什么推荐它？</h2><button class="text-btn" @click="showEvidence(restaurant!.evidenceIds, '关于这家餐厅的推荐依据')">查看依据</button></div><div class="reason-list"><div v-for="reason in reasons" :key="reason.title"><span><AppIcon name="check" :size="13" /></span><p><b>{{ reason.title }}</b><small>{{ reason.description }}</small></p></div></div><div class="section-heading"><h2>听听用餐体验</h2><span class="mock-label">演示评价</span></div><article v-for="review in reviews" :key="review.id" class="review-card"><div class="review-meta"><span class="review-avatar"><AppIcon name="quote" :size="17" /></span><span><b>示例用餐记录</b><small>{{ review.date }}</small></span><i>环境与体验</i></div><blockquote>{{ review.text }}</blockquote><button class="review-source" @click="showEvidence([review.id], review.text)">{{ review.source }}<AppIcon name="chevron" :size="13" /></button></article><div class="section-heading"><h2>这一餐，在哪里</h2><span>高德地图</span></div><div class="detail-map"><AMapView :restaurants="[restaurant]" :selected-ids="[restaurant.id]" :center="restaurant.coordinates" mini /></div><p class="location-note"><AppIcon name="info" :size="13" />演示位置不对应真实门店，请勿据此出行。</p><button class="caveat" @click="showEvidence([restaurant!.evidenceIds[2]!], restaurant!.caveat)"><AppIcon name="info" :size="17" /><span>{{ restaurant.caveat }}</span><AppIcon name="chevron" :size="15" /></button></div><div class="bottom-action"><a class="btn btn-primary" :href="mapUrl" target="_blank" rel="noopener noreferrer"><AppIcon name="map" :size="20" />在高德查看演示位置<AppIcon name="external" :size="17" /></a><button class="text-btn" @click="router.push('/map')">还想再看看其他餐厅</button></div><EvidenceSheet :open="evidenceOpen" :ids="evidenceIds" :claim="claim" @close="evidenceOpen = false" /></section></template>
<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { restaurants, evidence } from '@/data/restaurants'
import { useDiningStore } from '@/stores/dining'
import { recommendationReasons } from '@/lib/recommendation'
import NavHeader from '@/components/NavHeader.vue'
import AppIcon from '@/components/AppIcon.vue'
import CharacterAvatar from '@/components/CharacterAvatar.vue'
import RestaurantArt from '@/components/RestaurantArt.vue'
import AMapView from '@/components/AMapView.vue'
import EvidenceSheet from '@/components/EvidenceSheet.vue'
const route = useRoute(), router = useRouter(), store = useDiningStore(), restaurant = computed(() => restaurants.find((r) => r.id === route.params.id))
const reviews = computed(() => evidence.filter((e) => e.restaurantId === restaurant.value?.id && e.kind === 'review'))
const reasons = computed(() => restaurant.value ? recommendationReasons(restaurant.value, store.filters) : [])
const evidenceOpen = ref(false), evidenceIds = ref<string[]>([]), claim = ref('')
const mapUrl = computed(() => restaurant.value ? `https://uri.amap.com/marker?position=${restaurant.value.coordinates.join(',')}&name=${encodeURIComponent(restaurant.value.name + '（演示位置）')}&coordinate=gaode&callnative=0` : '#')
function showEvidence(ids: string[], text: string) { evidenceIds.value = ids; claim.value = text; evidenceOpen.value = true }
function goBack() { if (window.history.state?.back) router.back(); else router.push(store.rawInput ? '/filter' : '/') }
watch(restaurant, (value) => { if (!value) { store.notify('没有找到这家餐厅，回去再挑挑吧'); router.replace(store.rawInput ? '/filter' : '/') } }, { immediate: true })
</script>
