font-size: var(--label-size); line-height: 1.9; margin: 8px 0 0; color: #786175; } } } .reason-list { >div { display: flex; align-items: flex-start; gap: 9px; padding: 10px 0; >span { border-radius: 50%; background: #dce5d4; width: 19px; height: 19px; display: grid; place-items: center; color: var(--green); flex: none; } p { margin: 1px 0 0; b { font-size: var(--label-size); font-weight: 600; display: block; } small { display: block; font-size: var(--small-size); color: var(--muted); line-height: 1.8; margin-top: 7px; } } } } .mock-label { font-size: 9px; background: #eee2ce; padding: 5px 8px; border-radius: 20px; color: #a1855e; } .review-card { border: 1px solid var(--line); border-radius: 16px; padding: 17px; background: var(--paper); .review-meta { display: flex; align-items: center; gap: 8px; .review-avatar { width: 32px; height: 32px; border-radius: 50%; background: #e7dfcc; display: grid; place-items: center; color: #a08965; } >span:nth-child(2) { b { font-size: var(--label-size); font-weight: 500; display: block; } small { font-size: 9px; color: #a99885; display: block; margin-top: 3px; } } i { font-size: 9px; margin-left: auto; color: var(--green); font-style: normal; } } blockquote { font-size: var(--body-size); line-height: 1.9; color: #74636d; margin: 16px 0; } .review-source { display: flex; align-items: center; justify-content: space-between; border: 0; border-top: 1px dashed var(--line); background: none; width: 100%; color: #a18b73; padding: 12px 0 0; font-size: 9px; } } .detail-map { height: clamp(190px, 30vw, 300px); border: 1px solid #c6c8ae; border-radius: 16px; overflow: hidden; } .location-note { display: flex; align-items: center; gap: 5px; font-size: var(--small-size); color: #a28b73; } .caveat { display: flex; align-items: center; gap: 9px; width: 100%; margin: 22px 0 15px; background: #efe2cc; border: 1px solid #e1cba6; color: #9f7d49; border-radius: 12px; padding: 13px; text-align: left; span { flex: 1; font-size: var(--label-size); line-height: 1.8; } } .notice { font-size: var(--small-size); } } .bottom-action { flex-shrink: 0; text-align: center; .btn { font-size: var(--body-size); } .text-btn { padding-top: 15px; font-size: var(--small-size); } } }
</style>
